export {
  RadioGroup,
  RadioGroupLegend,
  Radio,
  RadioIndicator,
} from "./radio-group";

import { tv } from "tailwind-variants";

const radioGroup = tv({
  slots: {
    root: "flex flex-col items-start gap-2 text-foreground",
    legend: "text-sm font-semibold text-foreground",
    radio: [
      "flex size-4 shrink-0 items-center justify-center rounded-full border border-input bg-background transition-all duration-150 ease-default outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-checked:bg-primary data-checked:text-primary-foreground",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive/50",
      "focus-visible:data-invalid:ring-destructive/50",
      "dark:bg-input/15",
      "dark:data-checked:bg-primary dark:data-checked:text-primary-foreground",
    ],
    radioIndicator: [
      "flex items-center justify-center transition-[scale,opacity] duration-300 ease-default",
      "before:size-2 before:rounded-full before:bg-current",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
      "data-unchecked:hidden",
    ],
  },
});

export { radioGroup };

"use client";

import { mergeProps, useDirection, useRender } from "@base-ui/react";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { radioGroup } from "./radio-group.style";

function RadioGroup({ className, ...props }: BaseRadioGroup.Props) {
  const direction = useDirection();

  return (
    <BaseRadioGroup
      data-slot="radio-group"
      className={mergeSlotClassName(radioGroup().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function RadioGroupLegend({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  const legend = useRender({
    defaultTagName: "div",
    props: {
      ...mergeProps({ className: radioGroup().legend({ className }) }, props),
      "data-slot": "radio-group-legend",
    },
    render,
  });

  return legend;
}

function Radio({ className, ...props }: BaseRadio.Root.Props) {
  return (
    <BaseRadio.Root
      data-slot="radio"
      className={mergeSlotClassName(radioGroup().radio, className)}
      {...props}
    />
  );
}

function RadioIndicator({ className, ...props }: BaseRadio.Indicator.Props) {
  return (
    <BaseRadio.Indicator
      data-slot="radio-indicator"
      className={mergeSlotClassName(radioGroup().radioIndicator, className)}
      {...props}
    />
  );
}

export { RadioGroup, RadioGroupLegend, Radio, RadioIndicator };
